fn longest_increasing_streak(nums: &Vec<i32>) -> usize {
    if nums.is_empty() {
        return 0;
    }

    let mut max_len = 1;
    let mut curr_len = 1;

    for i in 1..nums.len() {
        if nums[i] > nums[i - 1] {
            // continue the current increasing streak
            curr_len += 1;
        } else {
            // reset streak length
            curr_len = 1;
        }
        if curr_len > max_len {
            max_len = curr_len;
        }
    }

    max_len
}

